function mergePatternImpl(intervals) {
  intervals.sort((a,b)=>a[0]-b[0]);
  const r=[intervals[0].slice()];
  for(let i=1;i<intervals.length;i++){
    const p=r[r.length-1],c=intervals[i];
    if(c[0]<=p[1])p[1]=Math.max(p[1],c[1]);
    else r.push([...c]);
  }
  return r;
}

function conflictPatternImpl(intervals) {
  intervals.sort((a,b)=>a[0]-b[0]);
  let conf=0,lastEnd=-Infinity;
  for(const[s,e]of intervals){
    if(s<lastEnd)conf++;
    else lastEnd=e;
  }
  return conf;
}

function resourcePatternImpl(intervals) {
  intervals.sort((a,b)=>a[0]-b[0]);
  const heap=[];
  for(const[s,e]of intervals){
    heap.sort((a,b)=>a-b);
    if(heap.length>0&&heap[0]<=s)heap.shift();
    heap.push(e);
  }
  return heap.length;
}

