function mergeImpl(intervals) {
  if (intervals.length<=1) return intervals;
  intervals.sort((a,b)=>a[0]-b[0]);
  const r=[intervals[0].slice()];
  for(let i=1;i<intervals.length;i++){
    const [s,e]=intervals[i],p=r[r.length-1];
    if(s<=p[1]) p[1]=Math.max(p[1],e);
    else r.push([s,e]);
  }
  return r;
}

function insertImpl(intervals, newInterval) {
  const r=[];let i=0;
  const [ns,ne]=newInterval;
  while(i<intervals.length&&intervals[i][1]<ns) r.push(intervals[i++]);
  let [ms,me]=[ns,ne];
  while(i<intervals.length&&intervals[i][0]<=me){
    ms=Math.min(ms,intervals[i][0]);
    me=Math.max(me,intervals[i][1]);
    i++;
  }
  r.push([ms,me]);
  while(i<intervals.length) r.push(intervals[i++]);
  return r;
}

