function eraseOverlapIntervalsImpl(intervals) {
  if (!intervals.length) return 0;
  intervals.sort((a,b)=>a[1]-b[1]);
  let kept=1, lastEnd=intervals[0][1];
  for(let i=1;i<intervals.length;i++){
    const [s,e]=intervals[i];
    if(s>=lastEnd){kept++;lastEnd=e;}
  }
  return intervals.length-kept;
}

function findMinArrowShotsImpl(points) {
  if(!points.length)return 0;
  points.sort((a,b)=>a[1]-b[1]);
  let arrows=1,pos=points[0][1];
  for(let i=1;i<points.length;i++){
    if(points[i][0]>pos){arrows++;pos=points[i][1];}
  }
  return arrows;
}

