const MODULE10_PROBLEMS = [
  {id:56,  title:'Merge Intervals',             pattern:'sort + scan',          nc150:true,  needsDP:false},
  {id:57,  title:'Insert Interval',             pattern:'three-phase scan',      nc150:true,  needsDP:false},
  {id:435, title:'Non-Overlapping Intervals',   pattern:'sort by end + greedy',  nc150:true,  needsDP:false},
  {id:452, title:'Min Arrows',                  pattern:'sort by end + greedy',  nc150:true,  needsDP:false},
  {id:252, title:'Meeting Rooms',               pattern:'sort + overlap check',  nc150:true,  needsDP:false},
  {id:253, title:'Meeting Rooms II',            pattern:'min-heap end times',    nc150:true,  needsDP:false},
  {id:55,  title:'Jump Game',                   pattern:'greedy maxReach',       nc150:true,  needsDP:false},
  {id:45,  title:'Jump Game II',                pattern:'greedy window',         nc150:true,  needsDP:false},
  {id:134, title:'Gas Station',                 pattern:'greedy start point',    nc150:true,  needsDP:false},
  {id:763, title:'Partition Labels',            pattern:'last occurrence map',   nc150:true,  needsDP:false},
];

function partitionLabelsImpl(s) {
  const last={};
  for(let i=0;i<s.length;i++)last[s[i]]=i;
  const r=[];let start=0,end=0;
  for(let i=0;i<s.length;i++){
    end=Math.max(end,last[s[i]]);
    if(i===end){r.push(end-start+1);start=i+1;}
  }
  return r;
}

function module10Summary() {
  return {
    total: MODULE10_PROBLEMS.length,
    nc150: MODULE10_PROBLEMS.filter(p=>p.nc150).length,
    patterns: [...new Set(MODULE10_PROBLEMS.map(p=>p.pattern))]
  };
}

function isGreedySafe(problemId) {
  const p = MODULE10_PROBLEMS.find(p=>p.id===problemId);
  return p ? !p.needsDP : false;
}
